import React, { useState } from 'react';
import { User, Search, X, Calendar, Clock, ShieldCheck, Zap, ChevronRight, Trophy, AlertOctagon, Fingerprint, Phone, ClipboardList, CheckCircle2 } from 'lucide-react';

const WorkersTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedWorker, setSelectedWorker] = useState(null);
  const [activeFilter, setActiveFilter] = useState('INFO');
  const [selectedShift, setSelectedShift] = useState(null);

  const workers = [
    { id: 'WK-102', name: 'KESHAV RAO', code: 'OP_ALPHA_01', area: 'GANDHI_NAGAR_DEPOT', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'WK-205', name: 'PRIYA DAS', code: 'OP_BETA_22', area: 'SILICON_VALLEY_HQ', status: 'ON_ROUTE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
  ];

  const workerStats = {
    currentSchedule: { 
      id: 'SCH-99', date: '22 MAR 2026', time: '06:00 - 14:00', route: 'CIRCUIT_A', 
      zone: 'ZONE_04', bins: ['B-882', 'B-112', 'B-090'], reports: '03_RESOLVED' 
    },
    history: [
      { id: 'SCH-98', date: '21 MAR 2026', time: '06:00 - 14:00', route: 'CIRCUIT_B', zone: 'ZONE_02', bins: ['B-441', 'B-001', 'B-992'], reports: '05_RESOLVED' },
      { id: 'SCH-97', date: '20 MAR 2026', time: '08:00 - 16:00', route: 'CIRCUIT_A', zone: 'ZONE_04', bins: ['B-882', 'B-112'], reports: 'NONE' },
    ],
    rewards: [{ id: 'RW-01', title: 'PERFECT_ATTENDANCE', prize: '₹2,000', date: 'MAR_2026' }],
    penalties: [{ id: 'PN-12', title: 'UNAUTHORIZED_STOP', fine: '₹200', date: '10_MAR' }]
  };

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 🔍 HEADER SECTION */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#CAD23C] p-6 rounded-[32px] border-[5px] border-[#47510B] shadow-[8px_8px_0_0_#47510B] shrink-0">
        <div className="flex items-center gap-4 text-[#47510B]">
          <Fingerprint size={40} />
          <h1 className="text-3xl leading-none">WORKER_OPERATIONS</h1>
        </div>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/40" size={20} />
          <input 
            type="text" 
            placeholder="FILTER_STAFF..." 
            className="w-full bg-white border-[4px] border-[#47510B] rounded-2xl p-4 pl-12 outline-none shadow-[4px_4px_0_0_#47510B]"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 📋 WORKER LIST (Grid) */}
      <div className="flex-grow overflow-y-auto pr-2 pb-28 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {workers.map(w => (
          <div key={w.id} onClick={() => setSelectedWorker(w)} className="bg-white border-[4px] border-[#47510B] p-6 rounded-[35px] shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 hover:shadow-[10px_10px_0_0_#A1AED1] transition-all cursor-pointer flex justify-between items-center min-h-[110px]">
            <div className="min-w-0">
              <p className="text-[10px] text-[#AB1717] mb-1 font-bold">{w.code}</p>
              <h3 className="text-2xl text-[#47510B] truncate leading-none mb-1">{w.name}</h3>
              <p className="text-[10px] opacity-40 font-bold">LOC: {w.area}</p>
            </div>
            <div className="bg-[#47510B] p-2 rounded-xl text-[#CAD23C] shrink-0">
              <ChevronRight size={24} strokeWidth={3} />
            </div>
          </div>
        ))}
      </div>

      {/* 🏗️ MAIN DOSSIER MODAL */}
      {selectedWorker && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-10">
          <div className="absolute inset-0 bg-[#47510B]/90 backdrop-blur-md" onClick={() => setSelectedWorker(null)} />

          <div className="relative w-full max-w-5xl h-[85vh] bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[20px_20px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* MODAL HEADER */}
            <div className="bg-[#47510B] p-8 text-white flex justify-between items-center border-b-[6px] border-[#CAD23C] shrink-0">
              <div className="flex gap-6 items-center">
                <div className="w-16 h-16 bg-[#CAD23C] border-4 border-white rounded-[22px] flex items-center justify-center text-[#47510B] shadow-[4px_4px_0_0_#000] shrink-0">
                  <User size={36} strokeWidth={3} />
                </div>
                <div className="min-w-0">
                  <span className="bg-[#FF5B03] px-3 py-1 rounded-full text-[10px] border-2 border-white inline-block mb-1">ID: {selectedWorker.id}</span>
                  <h2 className="text-3xl md:text-5xl leading-none truncate tracking-tighter">{selectedWorker.name}</h2>
                </div>
              </div>
              <button onClick={() => setSelectedWorker(null)} className="bg-[#AB1717] border-4 border-white p-3 rounded-2xl hover:scale-110 shadow-[4px_4px_0_0_#000] shrink-0 ml-4"><X size={28} /></button>
            </div>

            {/* NAV BAR (Tabs) */}
            <div className="bg-[#A1AED1] p-2 flex gap-2 overflow-x-auto no-scrollbar shrink-0 border-b-[4px] border-[#47510B]">
              {[
                { id: 'INFO', label: 'IDENTITY', icon: <Fingerprint size={16}/> },
                { id: 'SCHEDULES', label: 'TODAY', icon: <Zap size={16}/> },
                { id: 'HISTORY', label: 'LOG_HISTORY', icon: <History size={16}/> },
                { id: 'REWARDS', label: 'REWARDS', icon: <Trophy size={16}/> },
                { id: 'PENALTIES', label: 'PENALTIES', icon: <AlertOctagon size={16}/> }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-3 px-6 py-3 rounded-2xl text-[11px] font-black transition-all border-4 whitespace-nowrap ${activeFilter === f.id ? 'bg-[#FFF24D] text-[#47510B] border-[#47510B] shadow-[4px_4px_0_0_#000]' : 'bg-white/30 text-[#47510B] border-transparent hover:border-[#47510B]'}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* MODAL CONTENT AREA */}
            <div className="flex-grow p-8 overflow-y-auto pb-16 custom-scrollbar">

              {/* 1. IDENTITY SECTION */}
              {activeFilter === 'INFO' && (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in slide-in-from-right-4">
                  <div className="lg:col-span-8 space-y-6">
                    <div className="bg-white p-8 rounded-[40px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#CAD23C]">
                      <label className="text-[#AB1717] text-[10px] block mb-2 font-bold uppercase tracking-widest">RESIDENCE_LOC</label>
                      <p className="text-3xl md:text-4xl leading-tight text-[#47510B]">{selectedWorker.area}</p>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div className="bg-white p-6 rounded-3xl border-4 border-[#47510B] shadow-[6px_6px_0_0_#47510B]">
                        <label className="text-[10px] opacity-40 block mb-1">PHONE</label>
                        <p className="text-xl text-[#47510B]">{selectedWorker.phone}</p>
                      </div>
                      <div className="bg-white p-6 rounded-3xl border-4 border-[#47510B] shadow-[6px_6px_0_0_#A1AED1]">
                        <label className="text-[10px] opacity-40 block mb-1">JOIN_DATE</label>
                        <p className="text-xl text-[#47510B]">{selectedWorker.joined}</p>
                      </div>
                    </div>
                  </div>
                  <div className="lg:col-span-4 bg-[#CAD23C] border-[6px] border-[#47510B] rounded-[40px] p-8 flex flex-col items-center justify-center text-center shadow-[10px_10px_0_0_#47510B]">
                    <ShieldCheck size={64} className="mb-4 text-[#47510B]" />
                    <h3 className="text-3xl leading-none text-[#47510B]">STATUS:<br/>VERIFIED</h3>
                  </div>
                </div>
              )}

              {/* 2. CURRENT SCHEDULE */}
              {activeFilter === 'SCHEDULES' && (
                <div className="animate-in slide-in-from-bottom-4">
                  <div 
                    onClick={() => setSelectedShift(workerStats.currentSchedule)}
                    className="bg-white border-[5px] border-[#FF5B03] p-10 rounded-[50px] shadow-[12px_12px_0_0_#47510B] cursor-pointer hover:bg-[#FDFAD8] flex justify-between items-center group"
                  >
                    <div>
                      <p className="text-[#FF5B03] text-xs font-black mb-2">● LIVE_DUTY</p>
                      <h4 className="text-4xl md:text-5xl text-[#47510B] leading-none">{workerStats.currentSchedule.route}</h4>
                      <p className="text-xl opacity-50 mt-2 font-bold">{workerStats.currentSchedule.time}</p>
                    </div>
                    <div className="bg-[#47510B] text-white p-4 rounded-2xl group-hover:scale-110 transition-transform">
                      <ChevronRight size={40} />
                    </div>
                  </div>
                </div>
              )}

              {/* 3. LOG HISTORY */}
              {activeFilter === 'HISTORY' && (
                <div className="space-y-4 animate-in slide-in-from-bottom-4">
                  {workerStats.history.map((h, i) => (
                    <div key={i} onClick={() => setSelectedShift(h)} className="bg-white border-4 border-[#47510B] p-6 rounded-[35px] flex justify-between items-center shadow-[6px_6px_0_0_#CAD23C] cursor-pointer hover:bg-white/60 transition-all">
                      <div className="flex items-center gap-6 min-w-0">
                        <div className="bg-[#A1AED1] p-3 rounded-2xl border-2 border-black shrink-0"><History size={24} /></div>
                        <div className="min-w-0">
                          <h4 className="text-2xl text-[#47510B] truncate">{h.route}</h4>
                          <p className="text-[10px] font-black opacity-40">{h.date} // {h.time}</p>
                        </div>
                      </div>
                      <span className="text-[10px] font-black bg-[#47510B] text-white px-5 py-2 rounded-xl shrink-0 ml-4">VIEW_LOG</span>
                    </div>
                  ))}
                </div>
              )}

              {/* 4. REWARDS */}
              {activeFilter === 'REWARDS' && (
                <div className="space-y-4 animate-in slide-in-from-right-4">
                  {workerStats.rewards.map(r => (
                    <div key={r.id} className="bg-[#FFF24D] border-[5px] border-[#47510B] p-10 rounded-[50px] shadow-[10px_10px_0_0_#CAD23C] flex justify-between items-center">
                      <h4 className="text-4xl text-[#47510B]">{r.title}</h4>
                      <p className="text-5xl text-[#47510B] font-black">{r.prize}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* 5. PENALTIES */}
              {activeFilter === 'PENALTIES' && (
                <div className="space-y-4 animate-in slide-in-from-right-4">
                  {workerStats.penalties.map(p => (
                    <div key={p.id} className="bg-[#AB1717] border-[5px] border-black p-10 rounded-[50px] shadow-[10px_10px_0_0_#47510B] flex justify-between items-center text-white">
                      <h4 className="text-4xl italic">{p.title}</h4>
                      <p className="text-5xl font-black bg-white text-[#AB1717] px-8 py-2 rounded-2xl border-4 border-black">{p.fine}</p>
                    </div>
                  ))}
                </div>
              )}

            </div>
          </div>
        </div>
      )}

      {/* 🧾 SHIFT MANIFEST SUB-MODAL */}
      {selectedShift && (
        <div className="fixed inset-0 z-[1100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-black/70 backdrop-blur-md" onClick={() => setSelectedShift(null)} />
          <div className="relative w-full max-w-2xl bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[20px_20px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
             <div className="bg-[#47510B] p-6 text-white flex justify-between items-center border-b-4 border-[#CAD23C]">
                <h3 className="text-2xl flex items-center gap-3"><ClipboardList size={28}/> MANIFEST: {selectedShift.id}</h3>
                <button onClick={() => setSelectedShift(null)} className="bg-[#AB1717] border-2 border-white p-2 rounded-xl"><X size={24}/></button>
             </div>
             <div className="p-8 space-y-6">
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#CAD23C]">
                        <label className="text-[10px] opacity-60 block">ZONE</label>
                        <p className="text-2xl font-black text-[#47510B]">{selectedShift.zone}</p>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
                        <label className="text-[10px] opacity-60 block">DATE</label>
                        <p className="text-xl font-black text-[#47510B]">{selectedShift.date}</p>
                    </div>
                </div>
                <div>
                    <label className="text-xs text-[#AB1717] font-bold block mb-3 underline underline-offset-4 decoration-2">COLLECTED_BIN_CODES</label>
                    <div className="flex flex-wrap gap-2">
                        {selectedShift.bins.map(b => (
                            <span key={b} className="bg-[#FFF24D] text-[#47510B] border-4 border-[#47510B] px-4 py-1 rounded-xl text-lg font-black shadow-[4px_4px_0_0_#47510B]">{b}</span>
                        ))}
                    </div>
                </div>
                <div className="bg-[#CAD23C] p-6 rounded-3xl border-4 border-[#47510B] flex justify-between items-center shadow-[8px_8px_0_0_#47510B]">
                    <div>
                        <p className="text-[10px] font-bold text-[#47510B]/60 uppercase">WORK_REPORTS_RESOLVED</p>
                        <h5 className="text-3xl text-[#47510B] italic">{selectedShift.reports}</h5>
                    </div>
                    <CheckCircle2 size={40} className="text-[#47510B]" strokeWidth={3} />
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkersTab;
